(async () => {
  const b64 = "";
  const resp = await fetch('data:image/png;base64,' + b64);
  const blob = await resp.blob();
  const file = new File([blob], 'theta-desk-day3.png', { type: 'image/png' });
  const dt = new DataTransfer();
  dt.items.add(file);
  const editor = document.querySelector('[data-testid="tweetTextarea_0"]') || document.querySelector('[role="textbox"]');
  const ev = new DragEvent('drop', { bubbles: true, cancelable: true, dataTransfer: dt });
  editor.dispatchEvent(ev);
  return 'dropped, file size ' + blob.size;
})()